#include <bits/stdc++.h>
using namespace std;
using ull = unsigned long long;
int MOD;

int fpow(int a, int e) {
    int res = 1;
    while (e) {
        if (e & 1) res = (long long)res * a % MOD;
        a = (long long)a * a % MOD;
        e >>= 1;
    }
    return res;
}

const int N = 300000 + 5;
static array<array<ull, N>, 27> dp;
static array<int, N> fact;
static array<int, N> invfact;

int nPr(int n, int r) {
    return (long long)fact[n] * invfact[n - r] % MOD;
}

int main() {
    int n, K;
    scanf("%d%d%d", &n, &K, &MOD);

    if (n & 1) {
        printf("%d\n", fpow(K, n));
        return 0;
    }

    fact[0] = 1;
    for (int i = 1; i <= n; ++i)
        fact[i] = (long long)fact[i - 1] * i % MOD;

    invfact[n] = fpow(fact[n], MOD - 2);
    for (int i = n - 1; i >= 0; --i)
        invfact[i] = (long long)invfact[i + 1] * (i + 1) % MOD;

    dp[0][0] = 1;

    for (int k = 0; k < K; ++k) {
        for (int i = 1; i <= n; ++i) {
            if ((i & n) != i) continue;

            ull total = 0;
            int steps = 0;
            int hb = (1 << (31 - __builtin_clz(i)));
            int j = i - hb;

            while (true) {
                int jj = j + hb;
                total += dp[k][i ^ jj] * invfact[jj];

                if (++steps == 18) {
                    total %= MOD;
                    steps = 0;
                }

                if (j == 0) break;
                j = (j - 1) & i;
            }

            dp[k + 1][i] = total % MOD;
        }
    }

    int ans = 0;
    for (int i = 0; i <= K; ++i)
        (ans += 1LL * fact[n] * dp[i][n] % MOD * nPr(K, i) % MOD) %= MOD;

    printf("%d\n", (fpow(K, n) + MOD - ans) % MOD);
    return 0;
}
